{
  "predictors": [
    {
      "name": "Employee Satisfaction",
      "construction": "Use data from online job review platforms to create a measure of employee satisfaction for each publicly traded company.",
      "rationale": "Firms with high employee satisfaction may be more productive and innovative, leading to higher future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Customer Loyalty",
      "construction": "Use data from customer satisfaction surveys to create a measure of customer loyalty for each publicly traded company.",
      "rationale": "Firms with high customer loyalty may have more stable future revenues, leading to higher future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Supply Chain Complexity",
      "construction": "Use data from SEC filings to create a measure of supply chain complexity for each publicly traded company.",
      "rationale": "Firms with complex supply chains may be more vulnerable to shocks, leading to lower future returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Data Breach Risk",
      "construction": "Use data from cybersecurity ratings agencies to create a measure of data breach risk for each publicly traded company.",
      "rationale": "Firms with high data breach risk may face future costs and reputational damage, leading to lower future returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Executive Health",
      "construction": "Use data from executive physical exam disclosures to create a measure of executive health for each publicly traded company.",
      "rationale": "Firms with unhealthy executives may face leadership instability, leading to lower future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Political Risk Exposure",
      "construction": "Use data from lobbying disclosures and geographic revenue breakdowns in SEC filings to create a measure of political risk exposure for each publicly traded company.",
      "rationale": "Firms with high political risk exposure may face future costs and uncertainty, leading to lower future returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Media Sentiment",
      "construction": "Use data from news articles and social media sentiment analysis to create a measure of media sentiment for each publicly traded company.",
      "rationale": "Firms with positive media sentiment may have higher investor confidence, leading to higher future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "ESG Score",
      "construction": "Use data from environmental, social, and governance (ESG) ratings agencies to create a measure of ESG score for each publicly traded company.",
      "rationale": "Firms with high ESG scores may attract more sustainable investing, leading to higher future returns.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Product Recall History",
      "construction": "Use data from product recall databases to create a measure of product recall history for each publicly traded company.",
      "rationale": "Firms with a history of product recalls may face future costs and reputational damage, leading to lower future returns.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Diversity Score",
      "construction": "Use data from diversity and inclusion reports to create a measure of diversity score for each publicly traded company.",
      "rationale": "Firms with high diversity scores may be more innovative and resilient, leading to higher future returns.",
      "higher_returns_for": "High values of the measure"
    }
  ]
}
